function numberOfBeautifulIntegers(low, high, k) {
  const countUpTo = (num) => {
    const digits = String(num);
    const n = digits.length;
    const memo = new Map();

    const dfs = (pos, rem, diff, tight, started) => {
      if (pos === n) {
        return started && rem === 0 && diff === 0 ? 1 : 0;
      }
      const key = `${pos},${rem},${diff}`;
      if (started && !tight && memo.has(key)) {
        return memo.get(key);
      }
      const limit = tight ? Number(digits[pos]) : 9;
      let ways = 0;
      for (let digit = 0; digit <= limit; digit++) {
        const nextTight = tight && digit === limit;
        if (!started && digit === 0) {
          ways += dfs(pos + 1, 0, 0, nextTight, false);
          continue;
        }
        const nextDiff = diff + (digit % 2 === 0 ? 1 : -1);
        ways += dfs(pos + 1, (rem * 10 + digit) % k, nextDiff, nextTight, true);
      }
      if (started && !tight) {
        memo.set(key, ways);
      }
      return ways;
    };

    return dfs(0, 0, 0, true, false);
  };

  return countUpTo(high) - countUpTo(low - 1);
}

