function numberOfBeautifulIntegers(low, high, k) {
  let count = 0;
  for (let x = low; x <= high; x++) {
    if (x % k !== 0) continue;
    let even = 0, odd = 0;
    for (let rest = x; rest > 0; rest = Math.floor(rest / 10)) {
      if ((rest % 10) % 2 === 0) even++;
      else odd++;
    }
    if (even === odd) count++;
  }
  return count;
}

