function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const k = rand() < 0.2 ? pick(1, 3) : pick(1, 20);
  if (size === 'large') {
    const low = rand() < 0.5 ? pick(1, 1000) : pick(1, 1000000);
    const high = 1000000000 - pick(0, 1000000);
    return [low, high, k];
  }
  // Small ranges start at a random magnitude, sometimes just below a power of ten, so lengths change inside them.
  const length = pick(1, 9);
  let low = rand() < 0.3 ? 10 ** length - pick(1, 300) : pick(10 ** (length - 1), 10 ** length - 1);
  low = Math.max(1, low);
  const high = Math.min(1000000000, low + pick(0, rand() < 0.2 ? 5 : 3000));
  return [low, high, k];
}
